CREATE OR REPLACE FUNCTION public.nmis_public_portal_snapshot() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$ DECLARE v_active_providers bigint := 0; v_lgas bigint := 0; v_enrollees bigint := 0; v_capitation_rate numeric := 750; v_hospitals bigint := 0; v_pharmacies bigint := 0; v_diagnostics bigint := 0; v_population_year integer; v_population_month integer; v_population_period text; v_population_period_label text; v_last_updated timestamptz := now(); BEGIN SELECT count(*) INTO v_active_providers FROM public.providers WHERE lower(trim(coalesce(status, ''))) = 'active'; SELECT count(DISTINCT CASE WHEN regexp_replace(lower(trim(coalesce(p.lga, ''))), '[^a-z0-9]+', ' ', 'g') = 'akoko north east' THEN 'Akoko North-East' WHEN regexp_replace(lower(trim(coalesce(p.lga, ''))), '[^a-z0-9]+', ' ', 'g') = 'akoko north west' THEN 'Akoko North-West' WHEN regexp_replace(lower(trim(coalesce(p.lga, ''))), '[^a-z0-9]+', ' ', 'g') = 'akoko south east' THEN 'Akoko South-East' WHEN regexp_replace(lower(trim(coalesce(p.lga, ''))), '[^a-z0-9]+', ' ', 'g') = 'akoko south west' THEN 'Akoko South-West' WHEN regexp_replace(lower(trim(coalesce(p.lga, ''))), '[^a-z0-9]+', ' ', 'g') = 'ese odo' THEN 'Ese-Odo' WHEN regexp_replace(lower(trim(coalesce(p.lga, ''))), '[^a-z0-9]+', ' ', 'g') = 'ile oluji okeigbo' THEN 'Ile-Oluji/Oke-Igbo' ELSE trim(p.lga) END) INTO v_lgas FROM public.providers p WHERE lower(trim(coalesce(p.status, ''))) = 'active' AND nullif(trim(p.lga), '') IS NOT NULL; IF v_lgas > 18 THEN v_lgas := 18; END IF; SELECT e.reporting_year, e.reporting_month, max(e.period) INTO v_population_year, v_population_month, v_population_period FROM public.enrollees e WHERE e.record_status = 'valid' GROUP BY e.reporting_year, e.reporting_month ORDER BY e.reporting_year DESC, e.reporting_month DESC LIMIT 1; IF v_population_year IS NOT NULL AND v_population_month IS NOT NULL THEN v_population_period_label := trim(to_char(make_date(v_population_year, v_population_month, 1), 'FMMonth YYYY')); SELECT count(*) INTO v_enrollees FROM public.enrollees e WHERE e.record_status = 'valid' AND e.reporting_year = v_population_year AND e.reporting_month = v_population_month; END IF; SELECT COALESCE(rate, 750) INTO v_capitation_rate FROM public.nmis_system_settings WHERE setting_key = 'capitation_fee_per_enrollee' AND active = true; v_capitation_rate := COALESCE(v_capitation_rate, 750); SELECT count(*) INTO v_hospitals FROM public.providers WHERE lower(trim(coalesce(status, ''))) = 'active' AND category = 'HOSPITAL'; SELECT count(*) INTO v_pharmacies FROM public.providers WHERE lower(trim(coalesce(status, ''))) = 'active' AND category = 'PHARMACY'; SELECT count(*) INTO v_diagnostics FROM public.providers WHERE lower(trim(coalesce(status, ''))) = 'active' AND category = 'DIAGNOSTIC_CENTRE'; SELECT max(updated_at) INTO v_last_updated FROM public.enrollees WHERE record_status = 'valid' AND (v_population_year IS NULL OR (reporting_year = v_population_year AND reporting_month = v_population_month)); SELECT greatest(COALESCE(v_last_updated, now()), (SELECT max(updated_at) FROM public.providers), now()) INTO v_last_updated; RETURN jsonb_build_object( 'kpis', jsonb_build_object( 'registeredEnrollees', v_enrollees, 'populationPeriod', v_population_period, 'populationPeriodLabel', v_population_period_label, 'accreditedProviders', v_active_providers, 'lgasCovered', v_lgas, 'capitationRate', v_capitation_rate, 'hospitals', v_hospitals, 'pharmacies', v_pharmacies, 'diagnosticCentres', v_diagnostics ), 'transparency', jsonb_build_object( 'byLga', COALESCE(( SELECT jsonb_agg(jsonb_build_object('name', name, 'value', value) ORDER BY value DESC, name) FROM ( SELECT CASE WHEN regexp_replace(lower(trim(coalesce(e.lga, ''))), '[^a-z0-9]+', ' ', 'g') = 'akoko north east' THEN 'Akoko North-East' WHEN regexp_replace(lower(trim(coalesce(e.lga, ''))), '[^a-z0-9]+', ' ', 'g') = 'akoko north west' THEN 'Akoko North-West' WHEN regexp_replace(lower(trim(coalesce(e.lga, ''))), '[^a-z0-9]+', ' ', 'g') = 'akoko south east' THEN 'Akoko South-East' WHEN regexp_replace(lower(trim(coalesce(e.lga, ''))), '[^a-z0-9]+', ' ', 'g') = 'akoko south west' THEN 'Akoko South-West' WHEN regexp_replace(lower(trim(coalesce(e.lga, ''))), '[^a-z0-9]+', ' ', 'g') = 'ese odo' THEN 'Ese-Odo' WHEN regexp_replace(lower(trim(coalesce(e.lga, ''))), '[^a-z0-9]+', ' ', 'g') = 'ile oluji okeigbo' THEN 'Ile-Oluji/Oke-Igbo' ELSE trim(e.lga) END AS name, count(*)::bigint AS value FROM public.enrollees e WHERE e.record_status = 'valid' AND (v_population_year IS NULL OR (e.reporting_year = v_population_year AND e.reporting_month = v_population_month)) AND nullif(trim(e.lga), '') IS NOT NULL GROUP BY 1 ORDER BY count(*) DESC, 1 LIMIT 18 ) AS lga_summary ), '[]'::jsonb), 'byCategory', COALESCE(( SELECT jsonb_agg(jsonb_build_object('name', category, 'value', value) ORDER BY value DESC, category) FROM ( SELECT category, count(*)::bigint AS value FROM public.providers WHERE lower(trim(coalesce(status, ''))) = 'active' GROUP BY category ) AS category_summary ), '[]'::jsonb) ), 'featuredProviders', COALESCE(( SELECT jsonb_agg(jsonb_build_object( 'id', p.id, 'providerCode', p.provider_code, 'providerName', p.provider_name, 'category', p.category, 'ownership', p.ownership, 'lga', p.lga, 'state', p.state, 'services', COALESCE((SELECT array_agg(ps.service_name ORDER BY ps.service_name) FROM public.provider_services ps WHERE ps.provider_id = p.id), ARRAY[]::text[]) ) ORDER BY p.provider_name) FROM ( SELECT p.* FROM public.providers p WHERE lower(trim(coalesce(p.status, ''))) = 'active' ORDER BY p.provider_name LIMIT 6 ) AS p ), '[]'::jsonb), 'lastUpdated', v_last_updated ); END; $$ ;